using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Tilemaps;
using Framework.Grid;

namespace Framework.Tilemap
{
    /// <summary>
    /// グリッドマップのデータをUnityのTilemapへ描画する
    /// 汎用レンダラークラス。
    ///
    /// 複数レイヤーへの描画、部分更新、
    /// マップデータ変更時の自動更新に対応する。
    /// </summary>
    /// <typeparam name="T">
    /// グリッドの各マスに格納されるデータ型
    /// </typeparam>
    public class GridTilemapRenderer<T> : IDisposable
    {
        #region Nested Classes

        /// <summary>
        /// Tilemapとタイル選択処理を管理するレイヤー情報。
        /// </summary>
        private sealed class TilemapLayer
        {
            /// <summary>
            /// 描画先となるTilemap。
            /// </summary>
            public UnityEngine.Tilemaps.Tilemap Target { get; }

            /// <summary>
            /// 座標とマスデータから描画するタイルを選択する処理。
            /// nullを返した場合はタイルを消去する。
            /// </summary>
            public Func<Vector2Int, T, TileBase> TileSelector { get; }

            /// <summary>
            /// Tilemap上の描画開始位置。
            /// </summary>
            public Vector3Int Offset { get; }

            /// <summary>
            /// 描画レイヤーを生成する。
            /// </summary>
            /// <param name="target">描画先のTilemap</param>
            /// <param name="tileSelector">タイル選択処理</param>
            /// <param name="offset">描画位置のオフセット</param>
            public TilemapLayer(
                UnityEngine.Tilemaps.Tilemap target,
                Func<Vector2Int, T, TileBase> tileSelector,
                Vector3Int offset)
            {
                Target = target;
                TileSelector = tileSelector;
                Offset = offset;
            }
        }

        #endregion

        #region Fields

        /// <summary>
        /// 描画対象となるグリッドマップ。
        /// </summary>
        private GridMap<T> map;

        /// <summary>
        /// 登録されている描画レイヤーの一覧。
        /// </summary>
        private readonly List<TilemapLayer> layers =
            new List<TilemapLayer>();

        /// <summary>
        /// マップ変更時に自動描画するかどうか。
        /// </summary>
        private bool autoUpdate;

        /// <summary>
        /// インスタンスが破棄済みかどうか。
        /// </summary>
        private bool disposed;

        #endregion

        #region Properties

        /// <summary>
        /// 現在の描画対象マップ。
        /// </summary>
        public GridMap<T> Map => map;

        /// <summary>
        /// 登録されている描画レイヤーの数。
        /// </summary>
        public int LayerCount => layers.Count;

        /// <summary>
        /// 描画対象のマップが設定されているかどうか。
        /// </summary>
        public bool HasMap => map != null;

        /// <summary>
        /// マップ変更時の自動描画を有効・無効にする。
        /// </summary>
        public bool AutoUpdate
        {
            get => autoUpdate;

            set
            {
                ThrowIfDisposed();

                // 設定値が同じ場合は処理しない。
                if (autoUpdate == value)
                {
                    return;
                }

                UnsubscribeMapEvent();

                autoUpdate = value;

                SubscribeMapEvent();
            }
        }

        #endregion

        #region Constructors

        /// <summary>
        /// 汎用Tilemapレンダラーを生成する。
        /// </summary>
        /// <param name="map">描画対象のマップ</param>
        /// <param name="autoUpdate">
        /// マップ変更時に自動描画する場合はtrue
        /// </param>
        public GridTilemapRenderer(
            GridMap<T> map,
            bool autoUpdate = true)
        {
            this.autoUpdate = autoUpdate;

            SetMap(map);
        }

        #endregion

        #region Map Management

        /// <summary>
        /// 描画対象のマップを変更する。
        /// 変更前のマップの描画範囲は消去される。
        /// </summary>
        /// <param name="newMap">新しい描画対象マップ</param>
        public void SetMap(GridMap<T> newMap)
        {
            ThrowIfDisposed();

            if (newMap == null)
            {
                throw new ArgumentNullException(nameof(newMap));
            }

            if (ReferenceEquals(map, newMap))
            {
                return;
            }

            // 古いマップのイベント登録を解除する。
            UnsubscribeMapEvent();

            // 古いマップの描画内容を消去する。
            Clear();

            // 新しいマップを設定する。
            map = newMap;

            // 新しいマップのイベントを登録する。
            SubscribeMapEvent();
        }

        #endregion

        #region Layer Management

        /// <summary>
        /// 描画先となるTilemapをレイヤーとして登録する。
        /// 同じTilemapを重複して登録することはできない。
        /// </summary>
        /// <param name="target">描画先のTilemap</param>
        /// <param name="tileSelector">タイル選択処理</param>
        /// <param name="offset">描画位置のオフセット</param>
        public void AddLayer(
            UnityEngine.Tilemaps.Tilemap target,
            Func<Vector2Int, T, TileBase> tileSelector,
            Vector3Int offset = default(Vector3Int))
        {
            ThrowIfDisposed();

            if (target == null)
            {
                throw new ArgumentNullException(nameof(target));
            }

            if (tileSelector == null)
            {
                throw new ArgumentNullException(
                    nameof(tileSelector));
            }

            // 同じTilemapの重複登録を防止する。
            foreach (TilemapLayer layer in layers)
            {
                if (layer.Target == target)
                {
                    throw new InvalidOperationException(
                        "同じTilemapが既に登録されています。");
                }
            }

            // 新しい描画レイヤーを登録する。
            layers.Add(
                new TilemapLayer(
                    target,
                    tileSelector,
                    offset));
        }

        /// <summary>
        /// 指定された描画レイヤーの登録を解除する。
        /// </summary>
        /// <param name="target">登録解除対象のTilemap</param>
        /// <param name="clearTiles">
        /// 登録解除時にタイルを消去する場合はtrue
        /// </param>
        /// <returns>登録解除に成功した場合はtrue</returns>
        public bool RemoveLayer(
            UnityEngine.Tilemaps.Tilemap target,
            bool clearTiles = true)
        {
            ThrowIfDisposed();

            for (int i = 0; i < layers.Count; i++)
            {
                // 登録解除対象のレイヤーを取得する。
                TilemapLayer layer = layers[i];

                if (layer.Target != target)
                {
                    continue;
                }

                if (clearTiles)
                {
                    ClearLayer(layer);
                }

                layers.RemoveAt(i);

                return true;
            }

            return false;
        }

        #endregion

        #region Rendering

        /// <summary>
        /// 登録されている全レイヤーにマップ全体を描画する。
        /// </summary>
        public void RenderAll()
        {
            ThrowIfDisposed();

            if (map == null)
            {
                return;
            }

            foreach (TilemapLayer layer in layers)
            {
                RenderLayer(layer);
            }
        }

        /// <summary>
        /// 指定されたマスを全レイヤーに描画する。
        /// </summary>
        /// <param name="position">描画対象のマス座標</param>
        public void RenderCell(Vector2Int position)
        {
            ThrowIfDisposed();

            if (map == null || !map.IsInside(position))
            {
                return;
            }

            // 描画対象のマスデータを取得する。
            T cellData = map.GetCell(position);

            foreach (TilemapLayer layer in layers)
            {
                RenderCellToLayer(
                    layer,
                    position,
                    cellData);
            }
        }

        /// <summary>
        /// 指定された範囲内のマスを描画する。
        /// マップ範囲外の座標は除外される。
        /// </summary>
        /// <param name="area">描画対象の矩形範囲</param>
        public void RenderArea(RectInt area)
        {
            ThrowIfDisposed();

            if (map == null)
            {
                return;
            }

            // 描画範囲をマップ内に制限する。
            int minX = Mathf.Max(0, area.xMin);
            int minY = Mathf.Max(0, area.yMin);

            int maxX = Mathf.Min(map.Width, area.xMax);
            int maxY = Mathf.Min(map.Height, area.yMax);

            for (int y = minY; y < maxY; y++)
            {
                for (int x = minX; x < maxX; x++)
                {
                    RenderCell(new Vector2Int(x, y));
                }
            }
        }

        /// <summary>
        /// 指定されたレイヤーにマップ全体を描画する。
        /// </summary>
        /// <param name="layer">描画対象のレイヤー</param>
        private void RenderLayer(TilemapLayer layer)
        {
            if (layer.Target == null || map == null)
            {
                return;
            }

            // 一括描画に使用するタイル配列。
            TileBase[] tiles = new TileBase[map.Count];

            foreach (Vector2Int position in map.GetPositions())
            {
                // 二次元座標を一次元配列の番号に変換する。
                int index =
                    position.x + position.y * map.Width;

                // マスデータを取得する。
                T cellData = map.GetCell(position);

                // 描画ルールに従ってタイルを選択する。
                tiles[index] =
                    layer.TileSelector(position, cellData);
            }

            // Tilemap上の描画範囲を生成する。
            BoundsInt bounds = GetLayerBounds(layer);

            // 全タイルをまとめて描画する。
            layer.Target.SetTilesBlock(bounds, tiles);
        }

        /// <summary>
        /// 指定されたマスを指定レイヤーに描画する。
        /// </summary>
        /// <param name="layer">描画対象のレイヤー</param>
        /// <param name="position">描画対象の座標</param>
        /// <param name="cellData">描画対象のマスデータ</param>
        private void RenderCellToLayer(
            TilemapLayer layer,
            Vector2Int position,
            T cellData)
        {
            if (layer.Target == null)
            {
                return;
            }

            // Tilemap上の描画座標を算出する。
            Vector3Int tilePosition =
                new Vector3Int(position.x, position.y, 0)
                + layer.Offset;

            // 描画するタイルを選択する。
            TileBase tile =
                layer.TileSelector(position, cellData);

            // nullの場合は指定位置のタイルが消去される。
            layer.Target.SetTile(tilePosition, tile);
        }

        #endregion

        #region Clear Methods

        /// <summary>
        /// 登録された全レイヤーのマップ描画範囲を消去する。
        /// マップ範囲外にあるタイルは消去しない。
        /// </summary>
        public void Clear()
        {
            ThrowIfDisposed();

            foreach (TilemapLayer layer in layers)
            {
                ClearLayer(layer);
            }
        }

        /// <summary>
        /// 指定レイヤーのマップ描画範囲を消去する。
        /// </summary>
        /// <param name="layer">消去対象のレイヤー</param>
        private void ClearLayer(TilemapLayer layer)
        {
            if (layer.Target == null || map == null)
            {
                return;
            }

            // 全要素がnullのタイル配列を生成する。
            TileBase[] emptyTiles =
                new TileBase[map.Count];

            // マップの描画範囲のみ消去する。
            layer.Target.SetTilesBlock(
                GetLayerBounds(layer),
                emptyTiles);
        }

        #endregion

        #region Event Methods

        /// <summary>
        /// マップの変更イベントを登録する。
        /// </summary>
        private void SubscribeMapEvent()
        {
            if (map != null && autoUpdate)
            {
                map.CellChanged += OnCellChanged;
            }
        }

        /// <summary>
        /// マップの変更イベントを解除する。
        /// </summary>
        private void UnsubscribeMapEvent()
        {
            if (map != null)
            {
                map.CellChanged -= OnCellChanged;
            }
        }

        /// <summary>
        /// マップのデータが変更された際の処理。
        /// 変更されたマスのみ再描画する。
        /// </summary>
        /// <param name="position">変更されたマスの座標</param>
        /// <param name="previousValue">変更前のデータ</param>
        /// <param name="newValue">変更後のデータ</param>
        private void OnCellChanged(
            Vector2Int position,
            T previousValue,
            T newValue)
        {
            RenderCell(position);
        }

        #endregion

        #region Utility Methods

        /// <summary>
        /// 指定レイヤーのTilemap上の描画範囲を取得する。
        /// </summary>
        /// <param name="layer">対象の描画レイヤー</param>
        /// <returns>Tilemap上の描画範囲</returns>
        private BoundsInt GetLayerBounds(TilemapLayer layer)
        {
            return new BoundsInt(
                layer.Offset,
                new Vector3Int(
                    map.Width,
                    map.Height,
                    1));
        }

        /// <summary>
        /// 破棄済みのインスタンスが使用された場合に
        /// 例外を発生させる。
        /// </summary>
        private void ThrowIfDisposed()
        {
            if (disposed)
            {
                throw new ObjectDisposedException(
                    GetType().Name);
            }
        }

        #endregion

        #region IDisposable

        /// <summary>
        /// イベント登録と内部参照を解除する。
        /// 描画済みのタイルは消去しない。
        /// </summary>
        public void Dispose()
        {
            if (disposed)
            {
                return;
            }

            // マップからの変更通知を解除する。
            UnsubscribeMapEvent();

            // 登録されているレイヤー情報を破棄する。
            layers.Clear();

            // マップへの参照を解除する。
            map = null;

            disposed = true;
        }

        #endregion
    }
}
